implementation:
#include <stdio.h>
#include <stdlib.h>

#include "opj_image.h"
#include "opj_cparameters.h"

void calculate_tile_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno, OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1, OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec, OPJ_UINT32 *p_max_res) {
    if (!p_image || !p_cp || !p_tx0 || !p_tx1 || !p_ty0 || !p_ty1 || !p_dx_min || !p_dy_min || !p_max_prec || !p_max_res) {
        return;
    }

    OPJ_UINT32 num_components = p_image->numcomps;
    OPJ_UINT32 num_resolutions = p_cp->tw + 1;

    *p_tx0 = p_cp->tx0 + (p_tileno % p_cp->numXtiles) * p_cp->tdx;
    *p_tx1 = *p_tx0 + p_cp->tdx;

    *p_ty0 = p_cp->ty0 + (p_tileno / p_cp->numXtiles) * p_cp->tdy;
    *p_ty1 = *p_ty0 + p_cp->tdy;

    *p_dx_min = 0;
    *p_dy_min = 0;
    *p_max_prec = 0;
    *p_max_res = 0;

    for (OPJ_UINT32 compno = 0; compno < num_components; ++compno) {
        const opj_image_comp_t *comp = &p_image->comps[compno];
        const opj_tcp_t *tcp = &p_cp->tcp[compno];

        for (OPJ_UINT32 resno = 0; resno < num_resolutions; ++resno) {
            OPJ_UINT32 dx = tcp->dx[resno];
            OPJ_UINT32 dy = tcp->dy[resno];

            if (resno == 0) {
                *p_max_prec = 1;
            } else {
                *p_max_prec = (*p_max_prec > resno) ? *p_max_prec : resno;
            }

            if (resno == 0) {
                *p_dx_min = dx;
                *p_dy_min = dy;
            } else {
                *p_dx_min = (*p_dx_min < dx) ? *p_dx_min : dx;
                *p_dy_min = (*p_dy_min < dy) ? *p_dy_min : dy;
            }
        }

        *p_max_res = (*p_max_res > num_resolutions) ? *p_max_res : num_resolutions;
    }
}
